// Generated by scripts/prepare-stripe-dashboard.mjs. Do not edit this copy.
export type StripeSession = {
  id: string;
  url?: string | null;
  livemode: boolean;
  status: string | null;
  mode: string | null;
  payment_status: string;
  amount_total: number | null;
  currency: string | null;
  payment_intent: string | { id: string } | null;
  metadata: Record<string, string> | null;
};

export function requireSandboxKey(key: string | undefined): string {
  if (!key?.startsWith("sk_test_")) throw new Error("Stripe sandbox checkout is not configured. A secret test key is required.");
  return key;
}

export function validatePaidSession(session: StripeSession) {
  if (session.livemode !== false || !session.id.startsWith("cs_test_") || session.mode !== "payment") throw new Error("Only Stripe sandbox payments are accepted.");
  if (session.status !== "complete" || session.payment_status !== "paid") throw new Error("Payment is not complete.");
  const intent = typeof session.payment_intent === "string" ? session.payment_intent : session.payment_intent?.id;
  const orderId = session.metadata?.order_id;
  if (!orderId || !/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(orderId)) throw new Error("Order reference is missing.");
  if (!intent?.startsWith("pi_") || !Number.isSafeInteger(session.amount_total) || Number(session.amount_total) <= 0 || session.currency !== "usd") throw new Error("Payment details are invalid.");
  return { p_order_id: orderId, p_session_id: session.id, p_payment_intent_id: intent, p_amount_total: Number(session.amount_total), p_currency: session.currency };
}

import { createClient } from "https://esm.sh/@supabase/supabase-js@2";

export const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
  "Access-Control-Allow-Methods": "POST, OPTIONS",
};
export const json = (body: unknown, status = 200) => Response.json(body, { status, headers: corsHeaders });

export async function customerContext(request: Request) {
  const authorization = request.headers.get("Authorization");
  if (!authorization?.startsWith("Bearer ")) throw new Error("Sign in before checkout.");
  const url = Deno.env.get("SUPABASE_URL");
  const anon = Deno.env.get("SUPABASE_ANON_KEY");
  const service = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY");
  if (!url || !anon || !service) throw new Error("Checkout server is not configured.");
  const stripeSecret = requireSandboxKey(Deno.env.get("STRIPE_SECRET_KEY"));
  const customer = createClient(url, anon, { global: { headers: { Authorization: authorization } }, auth: { persistSession: false } });
  const { data, error } = await customer.auth.getUser();
  if (error || !data.user?.email) throw new Error("Sign in with a confirmed email before checkout.");
  return { customer, user: data.user, stripeSecret, admin: createClient(url, service, { auth: { persistSession: false } }) };
}

export async function stripeRequest(secret: string, path: string, body?: URLSearchParams, idempotencyKey?: string): Promise<StripeSession> {
  const response = await fetch(`https://api.stripe.com/v1/${path}`, {
    method: body ? "POST" : "GET",
    headers: { Authorization: `Bearer ${secret}`, "Content-Type": "application/x-www-form-urlencoded", ...(idempotencyKey ? { "Idempotency-Key": idempotencyKey } : {}) },
    body,
    signal: AbortSignal.timeout(15000),
  });
  const result = await response.json();
  if (!response.ok) throw new Error("Stripe could not process this checkout request. Please retry.");
  if (result.livemode !== false || !String(result.id).startsWith("cs_test_")) throw new Error("Only Stripe sandbox checkout is enabled.");
  return result;
}

export async function confirmPayment(admin: Awaited<ReturnType<typeof customerContext>>["admin"], session: StripeSession) {
  const params = validatePaidSession(session);
  const { error } = await admin.rpc("confirm_test_checkout", params);
  if (error) throw new Error("Your payment needs verification. Refresh your orders before attempting another payment.");
}


Deno.serve(async (request) => {
  if (request.method === "OPTIONS") return new Response("ok", { headers: corsHeaders });
  if (request.method !== "POST") return json({ error: "POST required" }, 405);
  try {
    const { customer, admin, user, stripeSecret } = await customerContext(request);
    const app = new URL(Deno.env.get("APP_URL") ?? "");
    if (app.protocol !== "https:" || app.search || app.hash) return json({ error: "Checkout return URL is not configured." }, 503);
    const body = await request.json();
    if (!body.location_id || !Array.isArray(body.lines) || !body.lines.length || body.lines.length > 100
      || !/^[0-9a-f-]{36}$/i.test(body.request_id ?? "")) return json({ error: "Choose a pickup store, products, and a valid checkout request." }, 400);
    const { data: order, error } = await customer.rpc("prepare_online_checkout", {
      p_request_id: body.request_id, p_location_id: body.location_id, p_lines: body.lines, p_discount_code: body.discount_code || null,
    });
    if (error) return json({ error: error.message, reset_request: error.message.includes("checkout was cancelled") }, 400);
    const { data: existing } = await customer.from("sales_orders").select("stripe_checkout_session_id,payment_status").eq("id", order.order_id).eq("created_by", user.id).single();
    if (existing?.stripe_checkout_session_id) {
      const previous = await stripeRequest(stripeSecret, `checkout/sessions/${existing.stripe_checkout_session_id}`);
      if (previous.status === "complete") return json({ url: `${app.href.replace(/\/$/, "")}/?checkout=success&session_id=${previous.id}` });
      if (previous.status === "open" && previous.url) return json({ url: previous.url, order_number: order.order_number, session_id: previous.id });
      if (previous.status === "expired") {
        await admin.rpc("cancel_unpaid_order", { p_order_id: order.order_id });
        return json({ error: "This checkout expired. Please start again.", reset_request: true }, 409);
      }
      return json({ error: "This checkout cannot be reopened. Please refresh your orders." }, 409);
    }

    // The same order always uses the same Stripe idempotency key, including retries
    // after a network timeout. A Stripe error must not cancel a possibly-created session.
    const params = new URLSearchParams({
      mode: "payment", customer_email: user.email!, client_reference_id: order.order_id,
      success_url: `${app.href.replace(/\/$/, "")}/?checkout=success&session_id={CHECKOUT_SESSION_ID}`,
      cancel_url: `${app.href.replace(/\/$/, "")}/?checkout=cancelled&order_id=${order.order_id}&session_id={CHECKOUT_SESSION_ID}`,
      "payment_method_types[0]": "card",
      "line_items[0][price_data][currency]": "usd",
      "line_items[0][price_data][product_data][name]": `Wasatch Cycle Works order ${order.order_number}`,
      "line_items[0][price_data][product_data][description]": "Demo order · Bikes and parts, pickup sales tax, and any applied discount. No real charge.",
      "line_items[0][price_data][unit_amount]": String(Math.round(Number(order.total) * 100)),
      "line_items[0][quantity]": "1", "metadata[order_id]": order.order_id, "metadata[order_number]": String(order.order_number),
    });
    const session = await stripeRequest(stripeSecret, "checkout/sessions", params, `wcw-checkout-${order.order_id}`);
    const { data: saved, error: saveError } = await admin.rpc("set_checkout_session", { p_order_id: order.order_id, p_session_id: session.id });
    if (saveError || !saved) return json({ error: "Could not link your payment session. Your bag is saved; retry this checkout." }, 502);
    if (session.status === "expired") {
      await admin.rpc("cancel_unpaid_order", { p_order_id: order.order_id });
      return json({ error: "This checkout expired. Please start again.", reset_request: true }, 409);
    }
    if (session.status === "complete") return json({ url: `${app.href.replace(/\/$/, "")}/?checkout=success&session_id=${session.id}` });
    if (!session.url) return json({ error: "Stripe did not return a checkout page. Please retry." }, 502);
    return json({ url: session.url, order_number: order.order_number, session_id: session.id });
  } catch (error) {
    return json({ error: error instanceof Error ? error.message : "Checkout could not be opened. Your bag is saved." }, 400);
  }
});
